import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    import yaml
    data = yaml.load(json_data, Loader=yaml.Loader)
    current = data
    for key in key_path:
        if key not in current:
            raise KeyError(f"Key '{key}' not found.")
        current = current[key]
    if not current:
        raise ValueError("No data found.")
    def extract_numbers(obj):
        nums = []
        if isinstance(obj, list):
            for item in obj:
                nums.extend(extract_numbers(item))
        elif isinstance(obj, dict):
            for val in obj.values():
                nums.extend(extract_numbers(val))
        elif isinstance(obj, (int, float)):
            nums.append(obj)
        elif isinstance(obj, str):
            try:
                nums.append(float(obj))
            except:
                pass
        return nums
    numbers = extract_numbers(current)
    if not numbers:
        raise ValueError("No numeric data found.")
    fig, ax = plt.subplots()
    sns.boxplot(data=numbers, ax=ax)
    ax.set_title('Boxplot of Extracted Numeric Data')
    return fig

